package config

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"slices"
	"strings"
)

// SettingsSchemaURL is where the settings JSON Schema is published
// (site/public/schema/settings.schema.json, generated by
// `itervox config schema`; see `make settings-schema`).
const SettingsSchemaURL = "https://itervox.dev/schema/settings.schema.json"

// Value types of a SettingField, as JSON Schema names them.
const (
	TypeBoolean = "boolean"
	TypeInteger = "integer"
	TypeNumber  = "number"
	TypeString  = "string"
	TypeArray   = "array"
	TypeObject  = "object"
)

// SettingField describes one layered setting for the schema and the
// dashboard's Settings page (#158).
type SettingField struct {
	// Key is the dotted path, e.g. "agent.max_turns".
	Key string
	// Type is the value's JSON Schema type (TypeBoolean, ...).
	Type string
	// Items is the element type of an array, or the value type of an object
	// used as a map. Empty for an object with its own shape (edited as JSON).
	Items string
	// Label and Description are what the Settings page shows.
	Label       string
	Description string
	// Group is the heading the Settings page lists the field under.
	Group string
	// Default is the built-in value; nil when it depends on the project
	// (workspace.root) or there is none.
	Default any
	// Enum lists the accepted values of a string.
	Enum []string
	// Minimum is the smallest accepted number.
	Minimum *float64
	// Live is set when a dashboard save applies the value to the running
	// daemon at once (through its cfgMu setter). Other values take effect
	// at the next restart or WORKFLOW.md reload.
	Live bool
	// Editor names the dashboard page that edits the value instead of the
	// Settings page ("profiles"); the Settings page shows it read-only.
	Editor string
	// Deprecated names the key that replaces this one.
	Deprecated string
}

// SettingFieldFor returns the registry entry for key.
func SettingFieldFor(key string) (SettingField, bool) {
	i := slices.IndexFunc(SettingFields, func(f SettingField) bool { return f.Key == key })
	if i < 0 {
		return SettingField{}, false
	}
	return SettingFields[i], true
}

// sectionInfo titles and describes each layered section in the schema.
var sectionInfo = map[string][2]string{
	"agent":     {"Agent", "The agent runner: command, capacity, retries, timeouts, review, SSH and rate limits."},
	"hub":       {"Hub", "The machine's itervox hub: one URL for every project (#228). Read at startup."},
	"polling":   {"Polling", "How often the tracker is polled."},
	"server":    {"Server", "The dashboard and API server."},
	"workspace": {"Workspace", "Per-issue working directories."},
}

// SettingsSchema returns the JSON Schema of a settings file, built from
// SettingFields.
func SettingsSchema() map[string]any {
	props := map[string]any{
		"$schema": map[string]any{"type": TypeString, "description": "The schema URL, for editor support."},
	}
	for _, section := range LayeredSections {
		info := sectionInfo[section]
		props[section] = objectSchema(info[0], info[1])
	}
	for _, f := range SettingFields {
		parts := strings.Split(f.Key, ".")
		node := props[parts[0]].(map[string]any)
		for _, p := range parts[1 : len(parts)-1] {
			children := node["properties"].(map[string]any)
			child, ok := children[p].(map[string]any)
			if !ok {
				child = objectSchema("", "")
				children[p] = child
			}
			node = child
		}
		node["properties"].(map[string]any)[parts[len(parts)-1]] = fieldSchema(f)
	}
	return map[string]any{
		"$schema":              "https://json-schema.org/draft/2020-12/schema",
		"$id":                  SettingsSchemaURL,
		"title":                "Itervox settings file",
		"description":          "A settings layer: ~/.itervox/settings.jsonc (user), .itervox/settings.jsonc (project, committed) or .itervox/settings.local.jsonc (project local, gitignored). Later layers win, and WORKFLOW.md wins over all of them. The files are JSONC: comments and trailing commas are allowed. Generated from the Itervox config registry; do not edit by hand.",
		"type":                 TypeObject,
		"additionalProperties": false,
		"properties":           props,
	}
}

func objectSchema(title, description string) map[string]any {
	s := map[string]any{"type": TypeObject, "additionalProperties": false, "properties": map[string]any{}}
	if title != "" {
		s["title"] = title
	}
	if description != "" {
		s["description"] = description
	}
	return s
}

func fieldSchema(f SettingField) map[string]any {
	s := map[string]any{"type": f.Type, "title": f.Label, "description": f.Description}
	if f.Group != "" {
		s["x-itervox-group"] = f.Group
	}
	if f.Default != nil {
		s["default"] = f.Default
	}
	if len(f.Enum) > 0 {
		s["enum"] = f.Enum
	}
	if f.Minimum != nil {
		s["minimum"] = *f.Minimum
	}
	switch {
	case f.Type == TypeArray && f.Items != "":
		s["items"] = map[string]any{"type": f.Items}
	case f.Type == TypeObject && f.Items != "":
		s["additionalProperties"] = map[string]any{"type": f.Items}
	}
	if f.Live {
		s["x-itervox-live"] = true
	}
	if f.Editor != "" {
		s["x-itervox-editor"] = f.Editor
	}
	if f.Deprecated != "" {
		s["deprecated"] = true
		s["x-itervox-replaced-by"] = f.Deprecated
	}
	return s
}

// SettingsSchemaJSON is SettingsSchema as the published file holds it:
// indented, keys sorted, ending in a newline.
func SettingsSchemaJSON() ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(SettingsSchema()); err != nil {
		return nil, fmt.Errorf("config: encode settings schema: %w", err)
	}
	return buf.Bytes(), nil
}

// ValidateSettingValue checks value against key's registry entry: the key
// must be a known layered setting and the value of its type (a nil value,
// which removes the key, always passes).
func ValidateSettingValue(key string, value any) error {
	f, ok := SettingFieldFor(key)
	if !ok {
		return fmt.Errorf("config: %s is not a setting Itervox reads (see `itervox config schema`)", key)
	}
	if value == nil {
		return nil
	}
	if err := checkType(f.Type, value); err != nil {
		return fmt.Errorf("config: %s: %w", key, err)
	}
	if s, isString := value.(string); isString && len(f.Enum) > 0 && !slices.Contains(f.Enum, s) {
		return fmt.Errorf("config: %s: %q is not one of %s", key, s, strings.Join(quoteAll(f.Enum), ", "))
	}
	if n, isNum := asFloat(value); isNum && f.Minimum != nil && n < *f.Minimum {
		return fmt.Errorf("config: %s: %v is below the minimum %v", key, value, *f.Minimum)
	}
	if f.Items == "" {
		return nil
	}
	switch t := value.(type) {
	case []any:
		for i, e := range t {
			if err := checkType(f.Items, e); err != nil {
				return fmt.Errorf("config: %s[%d]: %w", key, i, err)
			}
		}
	case map[string]any:
		for k, e := range t {
			if err := checkType(f.Items, e); err != nil {
				return fmt.Errorf("config: %s.%s: %w", key, k, err)
			}
		}
	}
	return nil
}

func quoteAll(ss []string) []string {
	out := make([]string, len(ss))
	for i, s := range ss {
		out[i] = fmt.Sprintf("%q", s)
	}
	return out
}

func asFloat(v any) (float64, bool) {
	switch t := v.(type) {
	case int:
		return float64(t), true
	case int64:
		return float64(t), true
	case float64:
		return t, true
	}
	return 0, false
}

func checkType(typ string, v any) error {
	ok := false
	switch typ {
	case TypeBoolean:
		_, ok = v.(bool)
	case TypeString:
		_, ok = v.(string)
	case TypeNumber:
		_, ok = asFloat(v)
	case TypeInteger:
		n, isNum := asFloat(v)
		ok = isNum && n == math.Trunc(n)
	case TypeArray:
		_, ok = v.([]any)
	case TypeObject:
		_, ok = v.(map[string]any)
	}
	if !ok {
		return fmt.Errorf("want %s, got %s", typ, ValueKind(v))
	}
	return nil
}
